import{_ as s,o as a,c as n,a2 as o}from"./chunks/framework.a6FUKr6c.js";const u=JSON.parse('{"title":"Dispatch","description":"","frontmatter":{},"headers":[],"relativePath":"guide/dispatch.md","filePath":"guide/dispatch.md","lastUpdated":1794153595000}'),t={name:"guide/dispatch.md"};function l(c,e,r,p,d,i){return a(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="dispatch" tabindex="-1">Dispatch <a class="header-anchor" href="#dispatch" aria-label="Permalink to &quot;Dispatch&quot;">​</a></h1><p>A tool can start runs of its <strong>own agent</strong> or of <strong>another agent</strong> of the app, and can wait for them to settle:</p><ul><li><code>dispatch(ctx, { role?, payload, idempotencyKey?, concurrencyKey?, address?, source? })</code> starts a run of the calling run&#39;s own agent.</li><li><code>dispatchTo(ctx, { agent, role?, payload, ... })</code> starts a run of <code>agent</code> (the calling run&#39;s own agent behaves exactly as <code>dispatch()</code>).</li><li><code>waitForDispatch(ctx, runs, { timeoutMs? })</code> pauses the calling run until every listed run settled and returns their outcomes.</li><li><code>dispatchTools({ roles?, agents?, wait? })</code> generates one tool per role, so a model dispatches without a hand-written tool (<a href="#generated-dispatch-tools">Generated dispatch tools</a>).</li></ul><p>A <a href="#simple-agents">simple agent</a> (<code>defineSimpleAgent({ run })</code>, no model) calls the same functions from plain code.</p><p>The new run (the child) has its own budget, its own approvals and its own concurrency key. A dispatch alone is fire and forget: the tool gets <code>{ runId, deduplicated }</code> and the calling run (the parent) goes on at once. With <code>waitForDispatch()</code> the parent waits durably, across restarts and replicas, and continues with the children&#39;s outcomes. A daily run that finds ten pull requests needing work dispatches one run per pull request instead of fixing them all inline under one budget; an audit fans out one run per area, waits for all of them and hands their findings to a reporter agent.</p><h2 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h2><p>An agent accepts dispatches only through <code>agent.on()</code> subscriptions in its channels, one per <strong>role</strong>. The child comes in on the channel <code>agent</code>, with the role as its subscription id, which <code>agentChannel()</code> registers:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#7F95A6;">// One agent, two kinds of run: the daily run lists and dispatches, each</span></span>
<span class="line"><span style="color:#7F95A6;">// dispatched run works on one pull request with its own context, budget and</span></span>
<span class="line"><span style="color:#7F95A6;">// approvals, in parallel with the others.</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> maintainer = defineModelAgent({</span></span>
<span class="line"><span style="color:#DCE9F2;">    name: </span><span style="color:#E7C58C;">&#39;maintainer&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    model,</span></span>
<span class="line"><span style="color:#DCE9F2;">    instructions: [</span></span>
<span class="line"><span style="color:#E7C58C;">        &#39;On the daily schedule: list the open pull requests and call dispatch_pr for each one that needs work.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#E7C58C;">        &#39;When started with a { pr, sha } payload: review that pull request only.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    ].join(</span><span style="color:#E7C58C;">&#39;\\n&#39;</span><span style="color:#DCE9F2;">),</span></span>
<span class="line"><span style="color:#DCE9F2;">    channels: [</span></span>
<span class="line"><span style="color:#DCE9F2;">        cron.on(</span><span style="color:#E7C58C;">&#39;0 6 * * *&#39;</span><span style="color:#DCE9F2;">),</span></span>
<span class="line"><span style="color:#7F95A6;">        // the opt-in: runs of this agent (and of the sweeper) may start runs of this agent under the role &#39;pr&#39;</span></span>
<span class="line"><span style="color:#DCE9F2;">        agent.on({</span></span>
<span class="line"><span style="color:#DCE9F2;">            role: </span><span style="color:#E7C58C;">&#39;pr&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">            schema: z.object({</span></span>
<span class="line"><span style="color:#DCE9F2;">                pr: z.string().describe(</span><span style="color:#E7C58C;">&#39;owner/repo#number&#39;</span><span style="color:#DCE9F2;">),</span></span>
<span class="line"><span style="color:#DCE9F2;">                sha: z.string().describe(</span><span style="color:#E7C58C;">&#39;the head commit&#39;</span><span style="color:#DCE9F2;">),</span></span>
<span class="line"><span style="color:#DCE9F2;">            }),</span></span>
<span class="line"><span style="color:#DCE9F2;">            description: </span><span style="color:#E7C58C;">&#39;Starts a run of its own for one pull request that needs work.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">            from: [</span><span style="color:#E7C58C;">&#39;sweeper&#39;</span><span style="color:#DCE9F2;">],</span></span>
<span class="line"><span style="color:#7F95A6;">            // one review per pushed commit, whichever run dispatched it</span></span>
<span class="line"><span style="color:#DCE9F2;">            idempotencyKey: (p) </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#E7C58C;"> \`</span><span style="color:#DCE9F2;">\${</span><span style="color:#E7C58C;">p</span><span style="color:#DCE9F2;">.</span><span style="color:#E7C58C;">pr</span><span style="color:#DCE9F2;">}</span><span style="color:#E7C58C;">@</span><span style="color:#DCE9F2;">\${</span><span style="color:#E7C58C;">p</span><span style="color:#DCE9F2;">.</span><span style="color:#E7C58C;">sha</span><span style="color:#DCE9F2;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#7F95A6;">            // never two runs on one pull request at a time</span></span>
<span class="line"><span style="color:#DCE9F2;">            concurrencyKey: (p) </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#DCE9F2;"> p.pr,</span></span>
<span class="line"><span style="color:#7F95A6;">            // the child&#39;s address: its tools reply on that pull request</span></span>
<span class="line"><span style="color:#DCE9F2;">            address: (p) </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#DCE9F2;"> p.pr,</span></span>
<span class="line"><span style="color:#DCE9F2;">            maxPerRun: </span><span style="color:#E7C58C;">20</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">        }),</span></span>
<span class="line"><span style="color:#DCE9F2;">    ],</span></span>
<span class="line"><span style="color:#DCE9F2;">    tools: {</span></span>
<span class="line"><span style="color:#DCE9F2;">        list_pull_requests: listPullRequests,</span></span>
<span class="line"><span style="color:#7F95A6;">        // dispatch_pr: input { pr, sha } from the role&#39;s schema, bound to the role per execution</span></span>
<span class="line"><span style="color:#DCE9F2;">        ...dispatchTools({ roles: [</span><span style="color:#E7C58C;">&#39;pr&#39;</span><span style="color:#DCE9F2;">] }),</span></span>
<span class="line"><span style="color:#DCE9F2;">        review_pull_request: reviewPullRequest,</span></span>
<span class="line"><span style="color:#DCE9F2;">    },</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">export</span><span style="color:#8FD0F2;"> const</span><span style="color:#DCE9F2;"> engine = </span><span style="color:#8FD0F2;">new</span><span style="color:#DCE9F2;"> Engine({</span></span>
<span class="line"><span style="color:#DCE9F2;">    store: createMemoryStore(),</span></span>
<span class="line"><span style="color:#DCE9F2;">    agents: [maintainer, sweeper, auditor, reporter],</span></span>
<span class="line"><span style="color:#7F95A6;">    // a bare engine lists the agent channel; @chamvi/app contributes it</span></span>
<span class="line"><span style="color:#DCE9F2;">    channels: [cronChannel(), agentChannel()],</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span></code></pre></div><p>With <a href="/guide/app"><code>@chamvi/app</code></a> the engine module contributes <code>agentChannel()</code>, so the name <code>agent</code> is taken (a user channel of that name clashes at setup). A dispatch to a role the agent does not declare is a <code>ValidationError</code> tool error: <code>Agent &quot;&lt;a&gt;&quot; has no dispatch role &quot;&lt;r&gt;&quot;: add agent.on({ role: &#39;&lt;r&gt;&#39; }) to its channels.</code></p><p><code>agent.on(options?)</code> takes:</p><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><code>role</code></td><td>The role, default <code>DEFAULT_DISPATCH_ROLE</code> (<code>&#39;default&#39;</code>). It is the subscription id, so it shares the agent&#39;s subscription ids (<code>http</code>, <code>cron:&lt;expression&gt;</code>, <code>webhook:&lt;path&gt;</code>, ...): two subscriptions with one id are an <code>InvalidAgentDefinitionError</code>. Role names follow the channel-name rule</td></tr><tr><td><code>schema</code></td><td>A Standard Schema the payload goes through; the child gets the parsed value. A failing payload is a <code>ValidationError</code> tool error and starts nothing. Without one the payload passes unchanged</td></tr><tr><td><code>maxPerRun</code></td><td>How many dispatches of this role one run may start over all its executions, default <code>DEFAULT_MAX_DISPATCHES_PER_RUN</code> (100). A positive integer, else <code>InvalidAgentDefinitionError</code> (also for a subscription built by hand, when the agent is registered)</td></tr><tr><td><code>from</code></td><td>The other agents whose runs may dispatch to this role (agent names; names not registered yet are allowed). The own agent always may</td></tr><tr><td><code>maxDepth</code></td><td>The deepest a run of this role may sit in a dispatch tree (a root run has depth 0), default <code>DEFAULT_DISPATCH_MAX_DEPTH</code> (1), at most <code>DISPATCH_DEPTH_MAX</code> (8)</td></tr><tr><td><code>concurrencyMaxRuns</code></td><td>A shared-store execution cap for runs of this role, as on every subscription (<a href="/guide/concurrency#shared-agent-and-subscription-ceilings">Concurrency</a>)</td></tr><tr><td><code>concurrencyKey(payload)</code></td><td>The child&#39;s concurrency key when the call gives none</td></tr><tr><td><code>idempotencyKey(payload)</code></td><td>The child&#39;s idempotency key when the call gives none</td></tr><tr><td><code>address(payload)</code></td><td>The child&#39;s address when the call gives none. Keep it deterministic: it feeds the dispatch&#39;s dedupe key, so another value on a redo is another call</td></tr><tr><td><code>description</code></td><td>What the role does: the description of its generated tool</td></tr></tbody></table><h2 id="starting-a-run" tabindex="-1">Starting a run <a class="header-anchor" href="#starting-a-run" aria-label="Permalink to &quot;Starting a run&quot;">​</a></h2><p>A tool calls <code>dispatch(ctx, { role, payload })</code> (the <code>audit</code> tool in <a href="#waiting-for-the-outcomes">Waiting for the outcomes</a> does); the role&#39;s hooks fill in what the call leaves out.</p><ul><li><code>payload</code> is required; <code>role</code> is a non-empty string; <code>idempotencyKey</code>, <code>concurrencyKey</code> and <code>address</code> are optional non-empty strings without NUL (the concurrency key and the address at most 255 characters); <code>source</code> is an optional <code>{ channel, address }</code> of a registered channel and an address of the same limits, nothing else (<a href="#outbound-in-a-child">Outbound in a child</a>). Anything else is a <code>ValidationError</code> tool error.</li><li>The child&#39;s envelope is <code>{ agent: &lt;target&gt;, trigger: &lt;role&gt;, channel: &#39;agent&#39;, payload, idempotencyKey, concurrencyKey?, address?, invoker?, parent }</code>. The model sees the channel, the role and the payload, like any run.</li><li><code>dispatch()</code> and <code>dispatchTo()</code> run inside a tool call or a simple agent&#39;s <code>run()</code> only; in the tools factory they throw <code>InvalidRunStateError</code>.</li></ul><h2 id="generated-dispatch-tools" tabindex="-1">Generated dispatch tools <a class="header-anchor" href="#generated-dispatch-tools" aria-label="Permalink to &quot;Generated dispatch tools&quot;">​</a></h2><p><code>dispatchTools(options)</code> returns one tool per role, to spread into an agent&#39;s <code>tools</code> (as <code>maintainer</code> above does):</p><table tabindex="0"><thead><tr><th>Option</th><th>Tools</th></tr></thead><tbody><tr><td><code>roles</code></td><td><code>dispatch_&lt;role&gt;</code> per role of the calling agent itself, calling <code>dispatch()</code></td></tr><tr><td><code>agents</code></td><td><code>[{ agent, roles }]</code>: <code>dispatch_&lt;agent&gt;_&lt;role&gt;</code> per role of another agent, calling <code>dispatchTo()</code></td></tr><tr><td><code>wait</code></td><td><code>true</code> or <code>{ timeoutMs }</code>: each tool waits for its child (<code>waitForDispatch()</code>) and returns its <code>DispatchOutcome</code> instead of <code>{ runId, deduplicated }</code>. The tool keeps its name</td></tr></tbody></table><ul><li>The tool&#39;s input is the role&#39;s schema when its JSON Schema is an object, so the payload is the input; any other schema (a string, an array, a union) or no schema becomes <code>{ payload }</code>. The tool validates the input with the role&#39;s schema for the model&#39;s sake but hands the raw input to <code>dispatch()</code>, which parses it once (a transforming schema is applied once).</li><li>The call passes no keys, no address and never a <code>source</code>: the role&#39;s <code>idempotencyKey()</code>, <code>concurrencyKey()</code> and <code>address()</code> decide them.</li><li>The tools are bound per execution to the roles as registered then, so a role replaced through <code>putAgent()</code> (a folder agent reloaded) gives the next execution its new schema and description. A target agent not registered yet keeps its tool with an untyped <code>payload</code>; a call answers with dispatch()&#39;s <code>ValidationError</code>.</li><li><code>InvalidAgentDefinitionError</code>: neither <code>roles</code> nor <code>agents</code>, a name breaking the agent-name rule, a tool name over 64 characters, an own role a plain tool set names and the agent does not declare (<code>defineModelAgent()</code>, <code>defineSimpleAgent()</code>), a role listed twice (<code>tool &quot;&lt;name&gt;&quot; is generated twice</code>), and, when the tool is bound (the run fails), a role schema that cannot be converted to JSON Schema or a generated name another tool of the agent&#39;s state or skills carries. Between your own tools the spread order decides.</li><li>A child is an internal destination: it inherits the run&#39;s taint and invoker, so the tools need no trust classification.</li></ul><h2 id="another-agent" tabindex="-1">Another agent <a class="header-anchor" href="#another-agent" aria-label="Permalink to &quot;Another agent&quot;">​</a></h2><p><code>dispatchTo()</code> reaches a role of another agent only when that role lists the caller in <code>from</code>: the receiving agent decides who may start its runs, the caller declares nothing. Otherwise it is a <code>ValidationError</code> tool error: <code>Agent &quot;&lt;target&gt;&quot; role &quot;&lt;r&gt;&quot; accepts no dispatches from agent &quot;&lt;caller&gt;&quot;.</code> An agent the engine does not hold is a <code>ValidationError</code> too.</p><p>A parent run with an invoker (a REST or MCP caller) dispatches to another agent only when that invoker holds <code>agent:&lt;target&gt;:run</code> (the permission <code>POST /agents/:name/runs</code> checks); the child carries the invoker unchanged, so a dispatch never widens grants. A run without an invoker (a cron run) passes.</p><h2 id="waiting-for-the-outcomes" tabindex="-1">Waiting for the outcomes <a class="header-anchor" href="#waiting-for-the-outcomes" aria-label="Permalink to &quot;Waiting for the outcomes&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> audit = defineTool({</span></span>
<span class="line"><span style="color:#DCE9F2;">    description: </span><span style="color:#E7C58C;">&#39;Hunts every area in a run of its own, then has the reporter draft the report.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    inputSchema: z.object({ areas: z.array(z.string()).min(</span><span style="color:#E7C58C;">1</span><span style="color:#DCE9F2;">) }),</span></span>
<span class="line"><span style="color:#DCE9F2;">    execute: </span><span style="color:#8FD0F2;">async</span><span style="color:#DCE9F2;"> ({ areas }, { context }) </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#DCE9F2;"> {</span></span>
<span class="line"><span style="color:#7F95A6;">        // effect-recorded: the call runs again on resume and gets the same runs back</span></span>
<span class="line"><span style="color:#8FD0F2;">        const</span><span style="color:#DCE9F2;"> hunts = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> Promise.all(areas.map((area) </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#DCE9F2;"> dispatch(context, {</span></span>
<span class="line"><span style="color:#DCE9F2;">            role: </span><span style="color:#E7C58C;">&#39;hunt&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">            payload: { area },</span></span>
<span class="line"><span style="color:#DCE9F2;">        })));</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F95A6;">        // pauses the run until every hunt settled, then returns one outcome per hunt, in order</span></span>
<span class="line"><span style="color:#8FD0F2;">        const</span><span style="color:#DCE9F2;"> findings = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> waitForDispatch(context, hunts);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F95A6;">        // a run of another agent, whose &#39;draft&#39; role lists &#39;auditor&#39; in from</span></span>
<span class="line"><span style="color:#8FD0F2;">        const</span><span style="color:#DCE9F2;"> draft = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> dispatchTo(context, {</span></span>
<span class="line"><span style="color:#DCE9F2;">            agent: </span><span style="color:#E7C58C;">&#39;reporter&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">            role: </span><span style="color:#E7C58C;">&#39;draft&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">            payload: { findings },</span></span>
<span class="line"><span style="color:#DCE9F2;">        });</span></span>
<span class="line"><span style="color:#8FD0F2;">        const</span><span style="color:#DCE9F2;"> report = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> waitForDispatch(context, draft, { timeoutMs: </span><span style="color:#E7C58C;">60</span><span style="color:#DCE9F2;"> * </span><span style="color:#E7C58C;">60</span><span style="color:#DCE9F2;"> * </span><span style="color:#E7C58C;">1000</span><span style="color:#DCE9F2;"> });</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">        return</span><span style="color:#DCE9F2;"> report.status === </span><span style="color:#E7C58C;">&#39;completed&#39;</span><span style="color:#DCE9F2;"> ? report.output : { failed: report.error };</span></span>
<span class="line"><span style="color:#DCE9F2;">    },</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> auditor = defineModelAgent({</span></span>
<span class="line"><span style="color:#DCE9F2;">    name: </span><span style="color:#E7C58C;">&#39;auditor&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    model,</span></span>
<span class="line"><span style="color:#DCE9F2;">    instructions: </span><span style="color:#E7C58C;">&#39;Every Monday, audit the repository area by area.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    channels: [</span></span>
<span class="line"><span style="color:#DCE9F2;">        cron.on(</span><span style="color:#E7C58C;">&#39;0 3 * * 1&#39;</span><span style="color:#DCE9F2;">),</span></span>
<span class="line"><span style="color:#DCE9F2;">        agent.on({</span></span>
<span class="line"><span style="color:#DCE9F2;">            role: </span><span style="color:#E7C58C;">&#39;hunt&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">            schema: z.object({ area: z.string() }),</span></span>
<span class="line"><span style="color:#DCE9F2;">            maxPerRun: </span><span style="color:#E7C58C;">10</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">        }),</span></span>
<span class="line"><span style="color:#DCE9F2;">    ],</span></span>
<span class="line"><span style="color:#7F95A6;">    // no new dispatch once the whole tree used two million tokens</span></span>
<span class="line"><span style="color:#DCE9F2;">    budget: { maxSubtreeTokens: </span><span style="color:#E7C58C;">2_000_000</span><span style="color:#DCE9F2;"> },</span></span>
<span class="line"><span style="color:#DCE9F2;">    tools: { audit },</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> reporter = defineModelAgent({</span></span>
<span class="line"><span style="color:#DCE9F2;">    name: </span><span style="color:#E7C58C;">&#39;reporter&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    model,</span></span>
<span class="line"><span style="color:#DCE9F2;">    instructions: </span><span style="color:#E7C58C;">&#39;Draft an audit report from the findings in the payload.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    channels: [agent.on({ role: </span><span style="color:#E7C58C;">&#39;draft&#39;</span><span style="color:#DCE9F2;">, from: [</span><span style="color:#E7C58C;">&#39;auditor&#39;</span><span style="color:#DCE9F2;">] })],</span></span>
<span class="line"><span style="color:#DCE9F2;">    output: Output.object({ schema: z.object({ summary: z.string(), findings: z.array(z.string()) }) }),</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span></code></pre></div><p><code>waitForDispatch()</code> takes run ids or dispatch results: one in, one <code>DispatchOutcome</code> out; a list in, the outcomes in its order (duplicates kept, <code>[]</code> for an empty list).</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8FD0F2;">type</span><span style="color:#DCE9F2;"> DispatchOutcome = {</span></span>
<span class="line"><span style="color:#DCE9F2;">    runId: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    agent: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    role: string;</span></span>
<span class="line"><span style="color:#DCE9F2;">    status: </span><span style="color:#E7C58C;">&#39;completed&#39;</span><span style="color:#DCE9F2;"> | </span><span style="color:#E7C58C;">&#39;failed&#39;</span><span style="color:#DCE9F2;"> | </span><span style="color:#E7C58C;">&#39;cancelled&#39;</span><span style="color:#DCE9F2;"> | </span><span style="color:#E7C58C;">&#39;timeout&#39;</span><span style="color:#DCE9F2;">;</span></span>
<span class="line"><span style="color:#DCE9F2;">    output?: unknown;                           </span><span style="color:#7F95A6;">// completed: the child&#39;s run.output</span></span>
<span class="line"><span style="color:#DCE9F2;">    error?: { code: string; message: string };  </span><span style="color:#7F95A6;">// failed, cancelled or timed out</span></span>
<span class="line"><span style="color:#DCE9F2;">};</span></span></code></pre></div><ul><li>When every listed run settled already, it returns at once. Otherwise the parent pauses in <code>waiting</code> like an <a href="/guide/approvals#asking-from-a-tool">approval</a>: the step ends, the wait point <code>run.waiting</code> is <code>{ kind: &#39;dispatch&#39;, id, toolName, toolCallId, runIds, expiresAt }</code>, and the parent frees its claim and slot.</li><li>The last child that settles requeues the parent (on any replica); <code>tick()</code> heals a parent whose children settled while no engine pushed it, so the parent resumes exactly once. The parent&#39;s tool call then <strong>runs again from the start</strong>, as after an approval: <code>dispatch()</code> returns the recorded children and <code>waitForDispatch()</code> the recorded outcomes. Keep code before it free of side effects, or make them <a href="/guide/effect-tools">effect tools</a>.</li><li><code>output</code> is the child&#39;s stored <code>output</code>: its agent&#39;s <a href="/guide/agents#structured-output">structured output</a>, else the final text. Stages that return different shapes are different agents.</li><li>Only runs this run dispatched may be waited on (its own children, or a run another parent dispatched under the same idempotency key, which this run got back with <code>deduplicated: true</code>); any other id is a <code>ValidationError</code> before the run pauses.</li><li><code>timeoutMs</code> defaults to <code>DEFAULT_DISPATCH_WAIT_TIMEOUT_MS</code> (24 h), from 1 to <code>APPROVAL_TIMEOUT_MAX_MS</code>. At expiry the engine cancels the unsettled children this run dispatched itself; they come back <code>cancelled</code> with <code>error.code</code> <code>Timeout</code>. A child running on another replica (or interrupted) first has to see the cancel: the wait is answered once it settled, or after one more claim TTL (<code>claimTtlMs</code>), when it comes back <code>timeout</code>. A deduplicated run another parent owns keeps running and comes back <code>timeout</code>.</li><li>A tainted child taints the parent before its outcome reaches the parent&#39;s model (<a href="/guide/tools#untrusted-content-and-outbound-tools">Tools &amp; Tool Errors</a>).</li><li>Like <code>approve()</code>, it runs in a tool call only (in the tools factory and in a streaming tool&#39;s body it throws <code>InvalidRunStateError</code>). <code>engine.approve()</code> refuses a dispatch wait (<code>InvalidRunStateError</code>, HTTP 409); the approval inbox shows only children that wait for a human.</li></ul><h2 id="simple-agents" tabindex="-1">Simple agents <a class="header-anchor" href="#simple-agents" aria-label="Permalink to &quot;Simple agents&quot;">​</a></h2><p>A simple agent (<code>defineSimpleAgent()</code>) has <code>run(payload, ctx)</code> in place of a model and instructions. The engine runs it as a durable run: <code>dispatch()</code>, <code>dispatchTo()</code>, <code>waitForDispatch()</code>, <code>approve()</code> and <code>ctx.channels</code> work as inside a tool call, so its children carry lineage, it can wait on them and <code>budget.maxSubtreeTokens</code> applies, all without a model call:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#7F95A6;">// No model: run() lists, dispatches one child per pull request and waits.</span></span>
<span class="line"><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> sweeper = defineSimpleAgent({</span></span>
<span class="line"><span style="color:#DCE9F2;">    name: </span><span style="color:#E7C58C;">&#39;sweeper&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    description: </span><span style="color:#E7C58C;">&#39;Reviews every open pull request labelled &quot;ready&quot; in a run of its own.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">    channels: [cron.on(</span><span style="color:#E7C58C;">&#39;0 7 * * *&#39;</span><span style="color:#DCE9F2;">)],</span></span>
<span class="line"><span style="color:#DCE9F2;">    tools: {</span></span>
<span class="line"><span style="color:#7F95A6;">        // an effect tool records its result: the execution after the wait gets the same list back</span></span>
<span class="line"><span style="color:#DCE9F2;">        list_ready: defineEffectTool({</span></span>
<span class="line"><span style="color:#DCE9F2;">            description: </span><span style="color:#E7C58C;">&#39;Lists the open pull requests labelled &quot;ready&quot;.&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">            inputSchema: z.object({}),</span></span>
<span class="line"><span style="color:#DCE9F2;">            execute: </span><span style="color:#8FD0F2;">async</span><span style="color:#DCE9F2;"> () </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#DCE9F2;"> fetchOpenPullRequests(</span><span style="color:#E7C58C;">&#39;ready&#39;</span><span style="color:#DCE9F2;">),</span></span>
<span class="line"><span style="color:#DCE9F2;">        }),</span></span>
<span class="line"><span style="color:#DCE9F2;">    },</span></span>
<span class="line"><span style="color:#DCE9F2;">    run: </span><span style="color:#8FD0F2;">async</span><span style="color:#DCE9F2;"> (_payload, ctx) </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#DCE9F2;"> {</span></span>
<span class="line"><span style="color:#7F95A6;">        // ctx.tools holds the agent&#39;s tools by name (\`!\`: an index read under noUncheckedIndexedAccess)</span></span>
<span class="line"><span style="color:#8FD0F2;">        const</span><span style="color:#DCE9F2;"> prs = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> ctx.tools.list_ready!({}) </span><span style="color:#8FD0F2;">as</span><span style="color:#DCE9F2;"> { pr: string; sha: string }[];</span></span>
<span class="line"><span style="color:#7F95A6;">        // effect-recorded: the execution after the wait gets the same children back</span></span>
<span class="line"><span style="color:#8FD0F2;">        const</span><span style="color:#DCE9F2;"> children = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> Promise.all(prs.map((p) </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#DCE9F2;"> dispatchTo(ctx, {</span></span>
<span class="line"><span style="color:#DCE9F2;">            agent: </span><span style="color:#E7C58C;">&#39;maintainer&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">            role: </span><span style="color:#E7C58C;">&#39;pr&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">            payload: p,</span></span>
<span class="line"><span style="color:#DCE9F2;">        })));</span></span>
<span class="line"><span style="color:#7F95A6;">        // pauses the run (no claim, no slot) until every review settled</span></span>
<span class="line"><span style="color:#8FD0F2;">        const</span><span style="color:#DCE9F2;"> outcomes = </span><span style="color:#8FD0F2;">await</span><span style="color:#DCE9F2;"> waitForDispatch(ctx, children);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F95A6;">        // the run&#39;s output</span></span>
<span class="line"><span style="color:#8FD0F2;">        return</span><span style="color:#DCE9F2;"> outcomes.map(({ runId, status }) </span><span style="color:#8FD0F2;">=&gt;</span><span style="color:#DCE9F2;"> ({ runId, status }));</span></span>
<span class="line"><span style="color:#DCE9F2;">    },</span></span>
<span class="line"><span style="color:#DCE9F2;">});</span></span></code></pre></div><ul><li><code>ctx</code> is the <a href="/guide/agents#tools-and-their-context">tool context</a> plus <code>ctx.tools</code>: the agent&#39;s tools (after <code>toolPolicy</code>, state tools included) as functions by name. A call goes through the same wrapper as a model&#39;s: input validated against the tool&#39;s schema (<code>ValidationError</code>), effect-recorded, trust-classified (a tainting tool taints the run and its later children), gated, and it may ask for an approval. A tool error throws to <code>run()</code> as the error; a name the agent lacks is a <code>ValidationError</code>. Each call that completes (its output or its tool error) appends a <code>tool</code> step; a call that pauses the run appends none, and <code>resume()</code> appends the <code>wait</code> step instead.</li><li>What <code>run()</code> returns (JSON-serialisable) is the run&#39;s <code>output</code>, so a parent&#39;s <code>waitForDispatch()</code> gets it. A throw fails the run, a <code>ValidationError</code> from <code>dispatch()</code> included: there is no model to hand it back to. The run ends with one <code>tool</code> step named after the agent.</li><li><code>timeoutMs</code> bounds each execution; <code>maxSteps</code> and <code>maxTokens</code> do not apply, and a model <code>run()</code> calls itself through <code>resolveModel()</code> is not counted in the run&#39;s usage.</li><li><strong>The replay rule</strong>: a run that paused (an approval, a wait) or was recovered runs <code>run()</code> again <strong>from the start</strong>. Effect-recorded calls return their records: <code>dispatch()</code> and <code>dispatchTo()</code> the same children, <code>waitForDispatch()</code> and <code>approve()</code> their answers, <code>emit()</code> nothing new, an <a href="/guide/effect-tools">effect tool</a> through <code>ctx.tools</code> its first result. Everything else repeats, a read tool through <code>ctx.tools</code> too. The approval and wait ids come from counters per execution (<code>0:run:&lt;n&gt;</code> and <code>0:run:w&lt;n&gt;</code> for calls in <code>run()</code>, <code>0:run:&lt;call&gt;:&lt;n&gt;</code> inside the <code>&lt;call&gt;</code>-th <code>ctx.tools</code> call), so keep the order of those calls free of state that can change between executions (the time, randomness, a fresh read): the sweeper above reads its list through an effect tool, so the execution after the wait dispatches and waits on the same runs.</li><li>A <code>run()</code> that catches the pause and returns anyway still pauses, and one that catches a <code>FatalToolError</code> from <code>ctx.tools</code> still fails. A <code>ctx.tools</code> call <code>run()</code> left running finishes before the run pauses or settles, as a model step waits for all its calls.</li></ul><h2 id="keys-and-dedupe-across-runs" tabindex="-1">Keys and dedupe across runs <a class="header-anchor" href="#keys-and-dedupe-across-runs" aria-label="Permalink to &quot;Keys and dedupe across runs&quot;">​</a></h2><p>The claimed idempotency key is <code>dispatch:&lt;role&gt;:&lt;key&gt;</code> (or <code>sha256:&lt;hex&gt;</code> of it when it is longer than 255 characters), so two roles of one agent never share a child, where <code>&lt;key&gt;</code> is the call&#39;s <code>idempotencyKey</code>, else the role&#39;s <code>idempotencyKey(payload)</code>, else <code>&lt;parent run id&gt;:&lt;hash of agent, role, payload, concurrency key and address&gt;</code>.</p><p>A given key is <strong>not</strong> scoped to the parent run: a second run that dispatches the same key (the job run again, a replica) gets the first child back with <code>deduplicated: true</code>. Key it by what makes the work unique, for example the pull request and its head commit (<code>\${pr}@\${sha}</code>, as the role&#39;s <code>idempotencyKey</code> above), so a redo keeps the same key. A role&#39;s <code>idempotencyKey(payload)</code> sees only the payload: a key derived from the trigger (the day of <code>ctx.run.trigger.receivedAt</code>) needs a hand-written tool that passes <code>idempotencyKey</code> to <code>dispatch()</code>. Without a key, the default is scoped to the parent, so another parent with the same payload starts its own child. The idempotency scope is <code>&lt;target agent&gt;:agent</code> (plus the invoker), apart from every other channel&#39;s. A dispatch whose key deduplicates into the caller itself or a run up its lineage is refused (<code>ValidationError</code>): waiting on it would be a cycle that nothing settles.</p><p>That check stops at the lineage. Two runs in different subtrees whose keys deduplicate into each other (run A&#39;s dispatch gets run B back, B&#39;s dispatch gets A back) can each wait on the other. Nothing settles that cycle; the wait timeout ends it: both waits expire and read the other run as <code>timeout</code>, and neither cancels the other, since a run another run dispatched is never cancelled by a wait&#39;s expiry. Keep keys deterministic and tied to the work of one subtree (no key a run of another subtree can produce for its own caller), or give such waits a shorter <code>timeoutMs</code>.</p><p>The concurrency key works as for any run: two children with the same key never run at the same time, so one key per pull request keeps two fixes of one pull request apart. A child may take the agent and concurrency key that the caller (or a run up its lineage) holds: it then queues and starts only after that run settled, so &quot;run this after me&quot; needs no extra code. Mind a caller that pauses for an approval meanwhile: the child waits as long. Waiting for such a child with <code>waitForDispatch()</code> is refused (<code>ValidationError</code>), since the wait would hold the key the child needs and never end.</p><h2 id="the-effect-record" tabindex="-1">The effect record <a class="header-anchor" href="#the-effect-record" aria-label="Permalink to &quot;The effect record&quot;">​</a></h2><p>Each call is recorded under the effect key <code>&lt;runId&gt;:dispatch:&lt;hash of agent, role, payload, key, concurrency key and address&gt;</code> with the value <code>{ runId, deduplicated }</code>, so a step redone after a crash, an approval or a wait returns the recorded result and starts nothing. Identical calls in one step (parallel tool calls) share one dispatch. Dispatch is idempotent by itself, so a crash between the dispatch and the record still yields one child (the redo reads <code>deduplicated: true</code>).</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Per run and role</strong>: at most <code>maxPerRun</code> dispatches per target agent and role, counted durably across executions (the effect <code>dispatch-count:&lt;runId&gt;:&lt;agent&gt;:&lt;role&gt;</code>), so a run that paused keeps its count. The count goes up before the dispatch, also for a deduplicated one; a crash in between spends that call&#39;s slot, and its redo reuses the slot (it never fails at the limit). Past the limit: <code>Run &lt;id&gt; reached its &lt;n&gt; dispatches of agent &quot;&lt;a&gt;&quot; role &quot;&lt;r&gt;&quot; (agent.on({ maxPerRun })).</code></li><li><strong>Depth</strong>: a child&#39;s depth is its parent&#39;s plus one, across agents. A role refuses a child deeper than its <code>maxDepth</code> (<code>Agent &quot;&lt;a&gt;&quot; role &quot;&lt;r&gt;&quot; accepts dispatches up to depth &lt;n&gt;.</code>), so with the default 1 a dispatched run cannot dispatch again.</li><li><strong>Subtree tokens</strong>: with <code>budget.maxSubtreeTokens</code> on an agent, a run of it (or any run below it) starts no new dispatch once that run&#39;s subtree usage reached it, summed from its children at the dispatch, never only the stored <code>subtreeUsage</code> (a <code>BudgetExceeded</code> tool error, see <a href="/guide/budgets#subtree-tokens">Budgets</a>). Children already running are not stopped.</li><li><strong>The invoker</strong> is inherited: the child gets the parent&#39;s invoker snapshot (none for a cron parent), so <code>requireToolPermission()</code> decides the same in the child as in the parent. The agent, the invoker and the parent come from the engine&#39;s copy of the run, so tool code that writes to <code>ctx.run</code> cannot change what a dispatch starts.</li></ul><h2 id="cancelling" tabindex="-1">Cancelling <a class="header-anchor" href="#cancelling" aria-label="Permalink to &quot;Cancelling&quot;">​</a></h2><p>Cancelling a run cancels the children it dispatched that have not settled, awaited or not, and theirs in turn (also when a registry change cancels it). A cascade lost to a store failure is completed by the engine&#39;s next poll, which cancels every unsettled run whose parent was cancelled. A run that completes or fails leaves its fire-and-forget children running. A run another parent dispatched under a shared idempotency key is never cancelled by a run that merely waited on it.</p><h2 id="outbound-in-a-child" tabindex="-1">Outbound in a child <a class="header-anchor" href="#outbound-in-a-child" aria-label="Permalink to &quot;Outbound in a child&quot;">​</a></h2><p>The <code>agent</code> channel has no <code>out</code>, so <code>ctx.channels.findOne()</code> without a name is <code>undefined</code> in a child, and its approvals go to the inbox and the API. Tools of a child name their channel and address, for example <code>ctx.channels.findOneOrFail(&#39;github&#39;).approve({ address: &#39;o/r#5&#39;, title: &#39;Merge?&#39; })</code>. The <code>address</code> given to the dispatch (else the role&#39;s <code>address(payload)</code>) becomes the child&#39;s <code>trigger.address</code> and <code>run.address</code> (shown in the dashboard), so a tool can read it back from <code>ctx.run.trigger.address</code>.</p><p>A child inherits its parent&#39;s <a href="/guide/tools#untrusted-content-and-outbound-tools">taint</a>, so every such <code>emit()</code> and <code>approve()</code> of a tainted child waits for the owner in the inbox first (&quot;Approve outbound execution from an untrusted run?&quot;). The <code>address</code> does not change that: a role&#39;s <code>address(payload)</code> reads the payload, which a generated tool takes from the model.</p><p><code>source: { channel, address }</code> names the one destination the child may use without that gate, as if the child had come in there:</p><div class="language-typescript"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#7F95A6;">// a daily sweep: the pull requests come from the GitHub API, read in code</span></span>
<span class="line"><span style="color:#8FD0F2;">for</span><span style="color:#DCE9F2;"> (</span><span style="color:#8FD0F2;">const</span><span style="color:#DCE9F2;"> pull </span><span style="color:#8FD0F2;">of</span><span style="color:#8FD0F2;"> await</span><span style="color:#DCE9F2;"> listOpenPulls(octokit, repo)) {</span></span>
<span class="line"><span style="color:#8FD0F2;">    await</span><span style="color:#DCE9F2;"> dispatch(ctx, {</span></span>
<span class="line"><span style="color:#DCE9F2;">        role: </span><span style="color:#E7C58C;">&#39;pr&#39;</span><span style="color:#DCE9F2;">,</span></span>
<span class="line"><span style="color:#DCE9F2;">        payload: { repo, number: pull.number },</span></span>
<span class="line"><span style="color:#DCE9F2;">        source: { channel: </span><span style="color:#E7C58C;">&#39;github&#39;</span><span style="color:#DCE9F2;">, address: </span><span style="color:#E7C58C;">\`</span><span style="color:#DCE9F2;">\${</span><span style="color:#E7C58C;">repo</span><span style="color:#DCE9F2;">}</span><span style="color:#E7C58C;">#</span><span style="color:#DCE9F2;">\${</span><span style="color:#E7C58C;">pull</span><span style="color:#DCE9F2;">.</span><span style="color:#E7C58C;">number</span><span style="color:#DCE9F2;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#DCE9F2;"> },</span></span>
<span class="line"><span style="color:#DCE9F2;">    });</span></span>
<span class="line"><span style="color:#DCE9F2;">}</span></span></code></pre></div><p>The child stores it as <code>trigger.parent.source</code>, so a resumed or replayed child keeps it, and its <code>emit()</code> and <code>approve()</code> to exactly that channel and address skip the outbound gate; every other destination is gated as before, and a child without <code>source</code> behaves as without this option. Classified tools (<code>github_create_comment</code> and the like) still exempt only the run&#39;s own source.</p><div class="warning custom-block"><p class="custom-block-title">The source is only as safe as the code that picks it</p><p>chamvi cannot tell where the address came from. Take it from trusted data your code read (an API response, configuration), never from model input: a tool that copies a model argument into <code>source</code> lets an injected prompt choose where the child posts unasked. The <a href="#generated-dispatch-tools">generated dispatch tools</a> never set it, a role has no hook for it, and <code>engine.dispatch()</code> drops it with <code>parent</code>. The exemption fixes the destination, not the content.</p></div><h2 id="lineage" tabindex="-1">Lineage <a class="header-anchor" href="#lineage" aria-label="Permalink to &quot;Lineage&quot;">​</a></h2><p>The child&#39;s <code>trigger.parent</code> is <code>{ kind: &#39;dispatch&#39;, runId, agent, role, depth, source? }</code> (<code>TriggerParent</code>), and the store keeps the parent&#39;s id as <code>run.parentRunId</code>. Only <code>dispatch()</code> and <code>dispatchTo()</code> set it: <code>engine.dispatch()</code> and a channel&#39;s <code>ctx.dispatch()</code> drop a <code>parent</code> a caller passes, so nobody forges lineage.</p><p><code>run.subtreeUsage</code> is the sum of every descendant&#39;s token usage, recomputed from the children when one settles. <code>GET /runs?filter[parent]=&lt;id&gt;</code> lists a run&#39;s children (<a href="/guide/http#routes">HTTP API</a>), and the <a href="/guide/ui">dashboard</a>&#39;s run page links the parent, lists the children and shows the subtree total.</p><h2 id="under-chamvi-run-job" tabindex="-1">Under <code>chamvi run-job</code> <a class="header-anchor" href="#under-chamvi-run-job" aria-label="Permalink to &quot;Under \`chamvi run-job\`&quot;">​</a></h2><p>A <a href="/guide/scheduler#one-shot-jobs">one-shot job</a> starts a whole engine over the shared store, so it runs the children its run dispatched too. A job whose run waits on its children does not end until they settle; it ends when the run or one of its descendants (also a run it waits on that another run dispatched) waits on an approval (<code>RunJobResult.waitingRunId</code> names the descendant). The drain at the end of the job interrupts fire-and-forget children still running; they requeue through recovery on the deployment and go on from their latest checkpoint.</p>`,54)])])}const y=s(t,[["render",l]]);export{u as __pageData,y as default};
